import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import Webcam from "react-webcam";
import {
  getAuth,
  RecaptchaVerifier,
  signInWithPhoneNumber,
  sendSignInLinkToEmail,
  isSignInWithEmailLink,
  signInWithEmailLink,
  createUserWithEmailAndPassword,
  sendEmailVerification,
  fetchSignInMethodsForEmail,
} from "firebase/auth";
import axios from "axios";
import "./Login.css";
import app, { auth } from "../../firebase";

const Login = () => {
  const navigate = useNavigate();
  const [name, setName] = useState("");
  const [aadhaarNumber, setAadhaarNumber] = useState("");
  const [phoneNumber, setPhoneNumber] = useState("");
  const [otp, setOtp] = useState("");
  const [otpSent, setOtpSent] = useState(false);
  const [confirmationResult, setConfirmationResult] = useState(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [showWebcam, setShowWebcam] = useState(false);
  const [verificationSuccess, setVerificationSuccess] = useState(false);
  const [captureSuccess, setCaptureSuccess] = useState(false);
  const [fingerprintImage, setFingerprintImage] = useState(null);
  const webcamRef = React.useRef(null);

  // NEW STATE VARIABLES FOR VOTER ID FEATURE
  const [showVoterIdForm, setShowVoterIdForm] = useState(false);
  const [voterId, setVoterId] = useState("");
  const [email, setEmail] = useState("");
  const [emailOtp, setEmailOtp] = useState("");
  const [emailOtpSent, setEmailOtpSent] = useState(false);
  const [emailVerified, setEmailVerified] = useState(false);
  const [emailPassword, setEmailPassword] = useState("");
  const [useEmailLink, setUseEmailLink] = useState(true);
  const [returnFromEmail, setReturnFromEmail] = useState(false);

  useEffect(() => {
    // Check if user is returning from email link verification
    if (isSignInWithEmailLink(auth, window.location.href)) {
      handleEmailLinkSignIn();
    }

    return () => {
      if (window.recaptchaVerifier) {
        window.recaptchaVerifier.clear();
        delete window.recaptchaVerifier;
      }
    };
  }, []);

  const reCaptchverify = () => {
    if (!window.recaptchaVerifier) {
      window.recaptchaVerifier = new RecaptchaVerifier(
        auth,
        "recaptcha-container",
        {
          size: "normal",
          callback: (response) => {
            console.log("reCAPTCHA solved", response);
          },
          "expired-callback": () => {
            console.log("reCAPTCHA expired");
            window.recaptchaVerifier.render().then((widgetId) => {
              window.recaptchaWidgetId = widgetId;
            });
          },
        }
      );
    }
    return window.recaptchaVerifier;
  };

  const verifyCode = () => {
    if (!confirmationResult) {
      setError("No confirmation result available");
      return Promise.reject("No confirmation result");
    }
    return confirmationResult.confirm(otp);
  };

  const validateInputs = () => {
    if (!name.trim()) {
      setError("Please enter your name as per Aadhaar");
      return false;
    }
    if (!aadhaarNumber || aadhaarNumber.length !== 12) {
      setError("Please enter a valid 12-digit Aadhaar number");
      return false;
    }
    if (!phoneNumber || phoneNumber.length !== 10) {
      setError("Please enter a valid 10-digit phone number");
      return false;
    }
    return true;
  };

  const sendOTP = async () => {
    setError("");
    if (!validateInputs()) return;

    setLoading(true);
    try {
      const verifier = reCaptchverify();
      const formattedPhone = `+91${phoneNumber}`;

      await verifier.render();
      const result = await signInWithPhoneNumber(
        auth,
        formattedPhone,
        verifier
      );

      setConfirmationResult(result);
      setOtpSent(true);
      setError("");
      console.log("OTP sent successfully");
    } catch (error) {
      console.error("OTP sending error:", error);
      setError(`Failed to send OTP: ${error.message}`);
      if (window.recaptchaVerifier) {
        window.recaptchaVerifier.clear();
        delete window.recaptchaVerifier;
      }
    } finally {
      setLoading(false);
    }
  };

  const verifyOTP = async () => {
    setError("");
    if (!otp || otp.length !== 6) {
      setError("Please enter a valid 6-digit OTP");
      return;
    }

    setLoading(true);
    try {
      await verifyCode();
      if (window.recaptchaVerifier) {
        window.recaptchaVerifier.clear();
        delete window.recaptchaVerifier;
      }

      const recaptchaContainer = document.getElementById("recaptcha-container");
      if (recaptchaContainer) {
        recaptchaContainer.innerHTML = "";
      }

      setVerificationSuccess(true);
      setShowWebcam(true);
      setError("");
    } catch (error) {
      setError("Invalid OTP. Please try again.");
      console.error("OTP verification error:", error);
    } finally {
      setLoading(false);
    }
  };

  const captureFaceImage = () => {
    const imageSrc = webcamRef.current.getScreenshot();
    if (!imageSrc) return;

    setShowWebcam(false);
    setShowVoterIdForm(true);
    setCaptureSuccess(true);
  };

  const handleFingerprintUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      setFingerprintImage(file);
    }
  };

  // FIREBASE EMAIL VERIFICATION FUNCTIONS
  const sendEmailVerificationLink = async () => {
    setError("");
    if (!email || !voterId) {
      setError("Please enter both email and voter ID");
      return;
    }

    if (!/\S+@\S+\.\S+/.test(email)) {
      setError("Please enter a valid email address");
      return;
    }

    setLoading(true);
    try {
      const actionCodeSettings = {
        url: `${window.location.origin}/login`,
        handleCodeInApp: true,
      };

      await sendSignInLinkToEmail(auth, email, actionCodeSettings);

      // Save email and voterId to localStorage
      window.localStorage.setItem("emailForSignIn", email);
      window.localStorage.setItem("voterIdForSignIn", voterId);
      window.localStorage.setItem(
        "userData",
        JSON.stringify({
          name,
          aadhaarNumber,
          phoneNumber,
          otp,
        })
      );

      setEmailOtpSent(true);
      setError("");
      alert(
        `✅ Verification link sent to ${email}! Please check your email and click the link to verify.`
      );
    } catch (error) {
      console.error("Email verification link error:", error);
      if (error.code === "auth/email-already-in-use") {
        setError(
          "This email is already registered. Please use a different email."
        );
      } else {
        setError(`Failed to send verification link: ${error.message}`);
      }
    } finally {
      setLoading(false);
    }
  };

  // Handle email link sign-in when user returns from email
  const handleEmailLinkSignIn = async () => {
    try {
      let email = window.localStorage.getItem("emailForSignIn");
      let voterId = window.localStorage.getItem("voterIdForSignIn");
      let userData = window.localStorage.getItem("userData");

      if (!email) {
        // If email is not in localStorage, prompt user
        setReturnFromEmail(true);
        setShowVoterIdForm(true);
        return;
      }

      const result = await signInWithEmailLink(
        auth,
        email,
        window.location.href
      );

      // Clear the URL parameters to remove the sign-in link
      window.history.replaceState({}, document.title, window.location.pathname);

      // Set the state with stored data
      if (userData) {
        const parsedData = JSON.parse(userData);
        setName(parsedData.name || "");
        setAadhaarNumber(parsedData.aadhaarNumber || "");
        setPhoneNumber(parsedData.phoneNumber || "");
        setOtp(parsedData.otp || "");
      }

      setEmail(email);
      if (voterId) setVoterId(voterId);
      setEmailVerified(true);
      setShowVoterIdForm(true);
      setReturnFromEmail(true);

      // Show success message
      setError("");
      alert(
        "✅ Email verified successfully! Please complete the verification process."
      );
    } catch (error) {
      console.error("Email link sign-in error:", error);
      setError(
        "Email verification failed. Please try sending the verification link again."
      );
      setReturnFromEmail(true);
      setShowVoterIdForm(true);
    }
  };

  const sendEmailOTPWithVerification = async () => {
    setError("");
    if (!email || !voterId) {
      setError("Please enter both email and voter ID");
      return;
    }

    if (!/\S+@\S+\.\S+/.test(email)) {
      setError("Please enter a valid email address");
      return;
    }

    setLoading(true);
    try {
      const methods = await fetchSignInMethodsForEmail(auth, email);

      if (methods.length > 0) {
        setError(
          "This email is already registered. Please use a different email."
        );
        setLoading(false);
        return;
      }

      const tempPassword = `Temp${voterId}${Date.now()}`;
      setEmailPassword(tempPassword);

      const userCredential = await createUserWithEmailAndPassword(
        auth,
        email,
        tempPassword
      );
      await sendEmailVerification(userCredential.user);

      // Store data in localStorage
      window.localStorage.setItem(
        "userData",
        JSON.stringify({
          name,
          aadhaarNumber,
          phoneNumber,
          otp,
        })
      );

      setEmailOtpSent(true);
      setError("");
      alert(
        `✅ Verification email sent to ${email}! Please check your inbox and verify your email address.`
      );
    } catch (error) {
      console.error("Email verification error:", error);
      if (error.code === "auth/email-already-in-use") {
        setError(
          "This email is already registered. Please use a different email."
        );
      } else {
        setError(`Failed to send verification email: ${error.message}`);
      }
    } finally {
      setLoading(false);
    }
  };

  const checkEmailVerification = async () => {
    setError("");
    setLoading(true);

    try {
      const user = auth.currentUser;

      if (user) {
        await user.reload();

        if (user.emailVerified) {
          setEmailVerified(true);
          setError("");
          submitFinalVerification();
        } else {
          setError(
            "Email not verified yet. Please check your inbox and verify your email."
          );
        }
      } else {
        setError(
          "No user found. Please try sending the verification email again."
        );
      }
    } catch (error) {
      console.error("Email verification check error:", error);
      setError("Failed to check email verification status.");
    } finally {
      setLoading(false);
    }
  };

  const submitFinalVerification = async () => {
    try {
      const imageSrc = webcamRef.current
        ? webcamRef.current.getScreenshot()
        : null;
      let faceImageFile = null;

      if (imageSrc) {
        // Convert base64 to blob
        const blob = await fetch(imageSrc).then((res) => res.blob());
        faceImageFile = new File([blob], `face_${Date.now()}.png`, {
          type: "image/png",
        });
      }

      const formData = new FormData();
      formData.append("name", name);
      formData.append("aadhaarNumber", aadhaarNumber);
      formData.append("phoneNumber", phoneNumber);
      formData.append("otp", otp);

      if (faceImageFile) {
        formData.append("faceImage", faceImageFile);
      }

      if (fingerprintImage) {
        formData.append("fingerprintImage", fingerprintImage);
      }

      const response = await axios.post(
        "http://localhost:5000/api/verify-user",
        formData
      );

      if (response.data.success) {
        setShowVoterIdForm(false);
        setError("");
        alert(
          "✅ Verification completed successfully! Data saved to database."
        );

        // Reset everything
        resetForm();

        // Clear localStorage
        window.localStorage.removeItem("emailForSignIn");
        window.localStorage.removeItem("voterIdForSignIn");
        window.localStorage.removeItem("userData");

        // Sign out from Firebase
        await auth.signOut();
      }
    } catch (error) {
      console.error("Submission error:", error);
      if (error.response?.data?.message?.includes("already voted")) {
        setError(`❌ ${error.response.data.message}`);
      } else {
        setError(
          "Failed to submit verification data: " +
            (error.response?.data?.message || error.message)
        );
      }
    }
  };

  const resetForm = () => {
    setName("");
    setAadhaarNumber("");
    setPhoneNumber("");
    setOtp("");
    setOtpSent(false);
    setVerificationSuccess(false);
    setCaptureSuccess(false);
    setFingerprintImage(null);
    setVoterId("");
    setEmail("");
    setEmailOtp("");
    setEmailOtpSent(false);
    setEmailVerified(false);
    setReturnFromEmail(false);
    setShowWebcam(false);
    setShowVoterIdForm(false);
    setError("");
  };

  // Add these input handlers
  const handleVoterIdChange = (e) => {
    setVoterId(e.target.value);
  };

  const handleEmailChange = (e) => {
    setEmail(e.target.value);
  };

  const handleEmailOtpChange = (e) => {
    setEmailOtp(e.target.value.replace(/\D/g, "").slice(0, 6));
  };

  const handleAadhaarChange = (e) => {
    setAadhaarNumber(e.target.value.replace(/\D/g, "").slice(0, 12));
  };

  const handlePhoneChange = (e) => {
    setPhoneNumber(e.target.value.replace(/\D/g, "").slice(0, 10));
  };

  const handleOtpChange = (e) => {
    setOtp(e.target.value.replace(/\D/g, "").slice(0, 6));
  };

  const goToAdminLogin = () => {
    navigate("/admin-login");
  };

  useEffect(() => {
    if (captureSuccess) {
      setError("");
    }
  }, [captureSuccess]);

  return (
    <div className="login-background">
      <div className="login-container">
        <div className="user-login">
          <h2>🗳️ E-Voting User Verification</h2>

          {returnFromEmail && (
            <div className="success-message">
              ✅ Welcome back! Your email has been verified. Please complete the
              verification process below.
            </div>
          )}

          <div id="recaptcha-container"></div>

          {error && !captureSuccess && (
            <div className="error-message">{error}</div>
          )}

          {verificationSuccess &&
            !showWebcam &&
            !captureSuccess &&
            !returnFromEmail && (
              <div className="success-message">
                OTP Verified! Please complete biometric verification.
              </div>
            )}

          {captureSuccess && !returnFromEmail && (
            <div className="success-message">
              ✅ Face Captured Successfully! Please complete voter information
              below.
            </div>
          )}

          {/* MAIN FORM - Only show if not returning from email or showing voter ID form */}
          {!showVoterIdForm && !returnFromEmail && (
            <>
              <input
                type="text"
                placeholder="Full Name as per Aadhaar"
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="form-input"
              />

              <input
                type="text"
                placeholder="Aadhaar Number (12 digits)"
                value={aadhaarNumber}
                onChange={handleAadhaarChange}
                className="form-input"
                maxLength="12"
              />

              <input
                type="text"
                placeholder="Phone Number (10 digits)"
                value={phoneNumber}
                onChange={handlePhoneChange}
                className="form-input"
                maxLength="10"
              />

              {!otpSent ? (
                <button
                  onClick={sendOTP}
                  className="otp-button"
                  disabled={loading}
                >
                  {loading ? "Sending OTP..." : "📱 Send OTP"}
                </button>
              ) : (
                <>
                  <input
                    type="text"
                    placeholder="Enter OTP (6 digits)"
                    value={otp}
                    onChange={handleOtpChange}
                    className="form-input"
                    maxLength="6"
                  />
                  <div className="button-group">
                    <button
                      onClick={verifyOTP}
                      className="verify-button"
                      disabled={loading}
                    >
                      {loading ? "Verifying..." : "✅ Verify OTP"}
                    </button>
                    <button
                      onClick={sendOTP}
                      className="resend-button"
                      disabled={loading}
                    >
                      🔄 Resend OTP
                    </button>
                  </div>
                </>
              )}
            </>
          )}

          {/* WEBCAM SECTION */}
          {showWebcam && !returnFromEmail && (
            <div className="webcam-section">
              <h3>📷 Face Verification</h3>
              <Webcam
                audio={false}
                ref={webcamRef}
                screenshotFormat="image/png"
                width={320}
                height={240}
                style={{ borderRadius: "8px", border: "2px solid #ddd" }}
              />
              <br />
              <div className="button-group">
                <button onClick={captureFaceImage} className="capture-button">
                  📸 Capture & Verify
                </button>
                <button
                  onClick={() => setShowWebcam(false)}
                  className="resend-button"
                >
                  ❌ Cancel
                </button>
              </div>

              <div
                className="fingerprint-section"
                style={{ marginTop: "20px" }}
              >
                <h4>👆 Fingerprint Upload (Optional)</h4>
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleFingerprintUpload}
                  className="form-input"
                />
              </div>
            </div>
          )}

          {/* VOTER ID FORM SECTION - Shows when returning from email or after face capture */}
          {(showVoterIdForm || returnFromEmail) && (
            <div
              className="webcam-section"
              style={{
                marginTop: "20px",
                background: "rgba(255,255,255,0.1)",
                padding: "20px",
                borderRadius: "10px",
              }}
            >
              <h3>
                {returnFromEmail
                  ? "✅ Email Verified Successfully!"
                  : "✅ Face Captured Successfully!"}
              </h3>
              <p
                style={{
                  color: "white",
                  textAlign: "center",
                  marginBottom: "20px",
                }}
              >
                {returnFromEmail
                  ? "Please complete your voter information and verification process"
                  : "Please complete your voter information"}
              </p>

              {/* Show basic info fields when returning from email */}
              {returnFromEmail && (
                <>
                  <input
                    type="text"
                    placeholder="Full Name as per Aadhaar"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className="form-input"
                  />

                  <input
                    type="text"
                    placeholder="Aadhaar Number (12 digits)"
                    value={aadhaarNumber}
                    onChange={handleAadhaarChange}
                    className="form-input"
                    maxLength="12"
                  />

                  <input
                    type="text"
                    placeholder="Phone Number (10 digits)"
                    value={phoneNumber}
                    onChange={handlePhoneChange}
                    className="form-input"
                    maxLength="10"
                  />

                  <input
                    type="text"
                    placeholder="Enter OTP (6 digits)"
                    value={otp}
                    onChange={handleOtpChange}
                    className="form-input"
                    maxLength="6"
                  />
                </>
              )}

              <input
                type="text"
                placeholder="Voter ID"
                value={voterId}
                onChange={handleVoterIdChange}
                className="form-input"
                maxLength="10"
              />

              <input
                type="email"
                placeholder="Email Address"
                value={email}
                onChange={handleEmailChange}
                className="form-input"
              />

              {!returnFromEmail && (
                <div style={{ marginBottom: "15px", textAlign: "center" }}>
                  <label style={{ color: "white", marginRight: "10px" }}>
                    <input
                      type="radio"
                      checked={useEmailLink}
                      onChange={() => setUseEmailLink(true)}
                      style={{ marginRight: "5px" }}
                    />
                    Email Link Verification
                  </label>
                  <label style={{ color: "white" }}>
                    <input
                      type="radio"
                      checked={!useEmailLink}
                      onChange={() => setUseEmailLink(false)}
                      style={{ marginRight: "5px" }}
                    />
                    Email OTP Verification
                  </label>
                </div>
              )}

              {!emailOtpSent && !returnFromEmail ? (
                <button
                  onClick={
                    useEmailLink
                      ? sendEmailVerificationLink
                      : sendEmailOTPWithVerification
                  }
                  className="otp-button"
                  disabled={loading}
                >
                  {loading
                    ? "Sending..."
                    : `📧 Send ${
                        useEmailLink
                          ? "Verification Link"
                          : "Verification Email"
                      }`}
                </button>
              ) : (
                <>
                  {!returnFromEmail && (
                    <div
                      className="success-message"
                      style={{ marginBottom: "15px" }}
                    >
                      ✅{" "}
                      {useEmailLink
                        ? "Verification link sent!"
                        : "Verification email sent!"}{" "}
                      Please check your email.
                    </div>
                  )}

                  {returnFromEmail && emailVerified ? (
                    <div
                      className="success-message"
                      style={{ marginBottom: "15px" }}
                    >
                      ✅ Email already verified! Ready to submit.
                    </div>
                  ) : null}

                  <div className="button-group">
                    <button
                      onClick={submitFinalVerification}
                      className="verify-button"
                      disabled={loading}
                    >
                      {loading ? "Submitting..." : "✅ Complete Verification"}
                    </button>

                    {!returnFromEmail && (
                      <button
                        onClick={
                          useEmailLink
                            ? sendEmailVerificationLink
                            : sendEmailOTPWithVerification
                        }
                        className="resend-button"
                        disabled={loading}
                      >
                        🔄 Resend {useEmailLink ? "Link" : "Email"}
                      </button>
                    )}
                  </div>
                </>
              )}

              {emailVerified && (
                <div className="success-message">
                  ✅ Email verified! Ready to submit your data.
                </div>
              )}
            </div>
          )}

          <div style={{ marginTop: "20px", textAlign: "center" }}>
            <button onClick={goToAdminLogin} className="admin-btn">
              👨‍💼 Admin Login
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
